<template>
  <div v-if="variant === 'underline'" class="w-full overflow-x-auto">
    <div class="flex gap-6 border-b border-border w-max">
      <NuxtLink v-for="item in items" :key="item.label" :to="item.to">
        <div
          :class="
            cn(
              'text-sm text-nowrap py-2 border-b-2 -mb-px transition-colors cursor-pointer flex items-center gap-2',
              item.selected
                ? 'border-primary font-medium'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            )
          "
        >
          <component :is="item?.icon?.icon" v-if="item.icon" :class="cn('stroke-muted-foreground', item.icon.class)" />
          <span>{{ item.label }}</span>
          <span v-if="!!item.count" class="text-xs text-accent-foreground rounded-full px-1 bg-border">
            {{ item.count }}
          </span>
        </div>
      </NuxtLink>
    </div>
  </div>
  <div v-else :class="cn('w-full overflow-x-auto', rounded && 'rounded-md')">
    <div :class="cn('flex gap-2 justify-between w-max bg-muted p-1', { 'rounded-md': rounded, 'w-full': stretched })">
      <NuxtLink v-for="item in items" :key="item.label" :to="item.to" :class="cn({ 'flex-1': stretched })">
        <div
          :class="
            cn(
              'text-sm text-nowrap w-full text-center px-4 py-2 flex justify-center items-center cursor-pointer hover:bg-accent-blind transition duration-300 rounded-md',
              item.selected && 'bg-white',
              stretched && 'px-3'
            )
          "
        >
          <component :is="item?.icon?.icon" v-if="item.icon" :class="cn('stroke-muted-foreground', item.icon.class)" />
          <span>{{ item.label }}</span>
          <span
            v-if="showZeroCount ? Number.isFinite(item.count) : !!item.count"
            class="text-xs text-accent-foreground rounded-full px-1 bg-border ml-2"
          >
            {{ item.count }}
          </span>
        </div>
      </NuxtLink>
    </div>
  </div>
</template>

<script setup lang="ts">
import { cn } from '@/components/ui/utils';
import type { NavigationItem } from '~/types/projects';

interface Props {
  items: Array<NavigationItem>;
  variant?: 'pill' | 'underline';
  /** Applies to the pill variant only; ignored when variant is "underline". */
  rounded?: boolean;
  /** Applies to the pill variant only; ignored when variant is "underline". */
  stretched?: boolean;
  // When true, the count badge renders for any numeric count, including 0.
  // When false (default), the badge is hidden for 0/undefined counts.
  showZeroCount?: boolean;
}
defineProps<Props>();
</script>
